/* prog53_dfs_cycle – detects a directed cycle in a graph.
 *
 * The program receives a list of directed edges on the command line,
 * each edge being a pair of integers “src dst”.  Vertices are numbered
 * from 0 to 7 (inclusive).  The number of arguments must therefore be
 * even (the program name does not count).  If any vertex number is
 * outside the range [0,7] or the argument count is wrong, the program
 * prints “INVALID_INPUT”.
 *
 * Otherwise the program builds an adjacency matrix for a directed
 * graph with at most 8 vertices, runs a depth‑first search to detect
 * a cycle, and finally prints either “CYCLE” (if a directed cycle
 * exists) or “ACYCLIC” (if the graph is acyclic).
 *
 * The output exactly matches the original binary’s observable
 * behaviour.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define MAXV 8

static int  adj[MAXV][MAXV];   /* adjacency matrix */
static int  color[MAXV];      /* 0 = unvisited, 1 = visiting, 2 = visited */
static bool found_cycle = false;

/* Depth‑first search with cycle detection */
static void dfs(int u)
{
    if (found_cycle)               /* early exit if a cycle is already found */
        return;

    color[u] = 1;                  /* mark as visiting */

    for (int v = 0; v < MAXV; ++v) {
        if (adj[u][v]) {           /* edge u → v exists */
            if (color[v] == 0) {
                dfs(v);
            } else if (color[v] == 1) {
                found_cycle = true;   /* back edge → cycle */
                return;
            }
        }
    }

    color[u] = 2;                  /* finished */
}

/* ---------------------------------------------------------------------- */
int main(int argc, char *argv[])
{
    /* ------------------------------------------------------------------
     * Input validation
     * ------------------------------------------------------------------ */
    if ((argc - 1) % 2 != 0) {          /* must be an even number of ints */
        puts("INVALID_INPUT");
        return 1;
    }

    /* Build adjacency matrix */
    for (int i = 1; i + 1 < argc; i += 2) {
        char *endptr;
        long src = strtol(argv[i],     &endptr, 10);
        if (*endptr != '\0') { puts("INVALID_INPUT"); return 1; }
        long dst = strtol(argv[i + 1], &endptr, 10);
        if (*endptr != '\0') { puts("INVALID_INPUT"); return 1; }

        if (src < 0 || src >= MAXV || dst < 0 || dst >= MAXV) {
            puts("INVALID_INPUT");
            return 1;
        }

        adj[(int)src][(int)dst] = 1;    /* directed edge */
    }

    /* ------------------------------------------------------------------
     * Cycle detection
     * ------------------------------------------------------------------ */
    for (int v = 0; v < MAXV; ++v) {
        if (color[v] == 0) {
            dfs(v);
            if (found_cycle)
                break;
        }
    }

    puts(found_cycle ? "CYCLE" : "ACYCLIC");
    return 0;
}
